s, err := choir.ReadFile("/workspace/platform/verifycheck/main.go")
if err != nil { println("READERR", err.Error()) } else {
	println(s)
}

w := func(path string, content string) int {
	n, e := choir.WriteFile(path, content)
	if e != nil { println("WRITEERR", path, e.Error()) }
	return n
}
patch, _ := choir.ReadFile("/selfdev/bundle/source.patch")
segments := map[string]string{}
curPath := ""
buf := []string{}
flush := func() {
	if curPath != "" { segments[curPath] = strings.Join(buf, "\n") }
}
for _, line := range strings.Split(patch, "\n") {
	if strings.HasPrefix(line, "diff --git ") {
		flush()
		curPath = ""
		buf = nil
		parts := strings.Split(line, " ")
		if len(parts) >= 4 { curPath = strings.TrimPrefix(parts[3], "b/") }
		continue
	}
	if curPath == "" { continue }
	buf = append(buf, line)
}
flush()

for p, body := range segments {
	out := []string{}
	for _, l := range strings.Split(body, "\n") {
		if strings.HasPrefix(l, "+++") { continue }
		if strings.HasPrefix(l, "+") { out = append(out, l[1:]) }
	}
	added := strings.Join(out, "\n") + "\n"
	dest := "/workspace/platform/.verify/nl_" + strings.ReplaceAll(p, "/", "_")
	w(dest, added)
}
r, _ := choir.Exec("sha256sum", []string{
	"/workspace/platform/.verify/nl_internal_selfdevfalsification_exercise.go",
	"/workspace/platform/.verify/nl_internal_selfdevfalsification_exercise_test.go",
	"/workspace/platform/.verify/nl_docs_evidence_m11-selfdev-episode-1791638468406-candidate-b.json",
})
println(r.Stdout)
println("LIVE:")
r2, _ := choir.Exec("sha256sum", []string{
	"/workspace/platform/internal/selfdevfalsification/exercise.go",
	"/workspace/platform/internal/selfdevfalsification/exercise_test.go",
	"/workspace/platform/docs/evidence/m11-selfdev-episode-1791638468406-candidate-b.json",
})
println(r2.Stdout)

run := func(name string, args []string) {
	r, err := choir.Exec(name, args)
	if err != nil {
		println("EXECERR", name, err.Error())
		return
	}
	println("###", name, strings.Join(args, " "), "exit", r.ExitCode)
	if r.Stdout != "" { println("OUT:", r.Stdout) }
	if r.Stderr != "" { println("ERR:", r.Stderr) }
}
run("sha256sum", []string{
	"/workspace/platform/.verify/internal_selfdevfalsification_exercise.go",
	"/workspace/platform/.verify/internal_selfdevfalsification_exercise_test.go",
	"/workspace/platform/.verify/docs_evidence_m11-selfdev-episode-1791638468406-candidate-b.json",
	"/workspace/platform/internal/selfdevfalsification/exercise.go",
	"/workspace/platform/internal/selfdevfalsification/exercise_test.go",
	"/workspace/platform/docs/evidence/m11-selfdev-episode-1791638468406-candidate-b.json",
})
run("gofmt", []string{"-l", "/workspace/platform/internal/selfdevfalsification/"})
run("env", []string{"GOPROXY=off", "GOTOOLCHAIN=local", "GOFLAGS=-mod=mod", "go", "-C", "/workspace/platform", "vet", "./internal/selfdevfalsification/"})

w := func(path string, content string) int {
	n, e := choir.WriteFile(path, content)
	if e != nil {
		println("WRITEERR", path, e.Error())
	}
	return n
}
patch, _ := choir.ReadFile("/selfdev/bundle/source.patch")
segments := map[string]string{}
curPath := ""
buf := []string{}
flush := func() {
	if curPath != "" {
		segments[curPath] = strings.Join(buf, "\n")
	}
}
for _, line := range strings.Split(patch, "\n") {
	if strings.HasPrefix(line, "diff --git ") {
		flush()
		curPath = ""
		buf = nil
		parts := strings.Split(line, " ")
		if len(parts) >= 4 {
			curPath = strings.TrimPrefix(parts[3], "b/")
		}
		continue
	}
	if curPath == "" { continue }
	buf = append(buf, line)
}
flush()

paths := []string{}
for p, body := range segments {
	out := []string{}
	for _, l := range strings.Split(body, "\n") {
		if strings.HasPrefix(l, "+++") { continue }
		if strings.HasPrefix(l, "+") {
			out = append(out, l[1:])
		}
	}
	added := strings.Join(out, "\n")
	dest := "/workspace/platform/.verify/" + strings.ReplaceAll(p, "/", "_")
	w(dest, added)
	paths = append(paths, dest)
}
println("extracted", len(paths))
for _, p := range paths { println(" ", p) }

w := func(path string, content string) int {
	n, e := choir.WriteFile(path, content)
	if e != nil {
		println("WRITEERR", path, e.Error())
	}
	return n
}
println("wrote", w("/workspace/platform/.verify/x.txt", "hi"))

for i := 0; i < 1; i++ {
	n, werr := choir.WriteFile("/workspace/platform/.verify/x.txt", "hi")
	if werr != nil {
		println("ERR", werr.Error())
	}
	println("wrote", n)
}
